/**
 * Create tickets: proof that a room code was generated by THIS server (POST /api/new-code), so a client can't
 * choose or squat codes. A ticket is an HMAC-SHA256 over "code.expires" with a secret only the server knows.
 * Uses Web Crypto (Workers and Node 20+); the check is constant-time (crypto.subtle.verify).
 */
const TTL_MS = 5 * 60 * 1000;
const enc = new TextEncoder();

const b64url = (bytes: Uint8Array): string => btoa(String.fromCharCode(...bytes)).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
function fromB64url(s: string): Uint8Array<ArrayBuffer> | null {
  if (!/^[A-Za-z0-9_-]*$/.test(s)) return null;
  try {
    const bin = atob(s.replace(/-/g, "+").replace(/_/g, "/"));
    const out = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    return out;
  } catch {
    return null;
  }
}

const importKey = (secret: string, usage: "sign" | "verify") =>
  crypto.subtle.importKey("raw", enc.encode(secret), { name: "HMAC", hash: "SHA-256" }, false, [usage]);

export async function issueTicket(secret: string, code: string, now: number, ttlMs = TTL_MS): Promise<{ ticket: string; expires: number }> {
  const expires = now + ttlMs;
  const sig = await crypto.subtle.sign("HMAC", await importKey(secret, "sign"), enc.encode(`${code}.${expires}`));
  return { ticket: b64url(new Uint8Array(sig)), expires };
}

export async function verifyTicket(secret: string, code: string, ticket: string, expires: number, now: number): Promise<boolean> {
  if (!secret || !Number.isFinite(expires) || expires < now) return false;
  const sig = fromB64url(ticket);
  if (!sig) return false;
  return crypto.subtle.verify("HMAC", await importKey(secret, "verify"), sig, enc.encode(`${code}.${expires}`));
}
